    h,w=len(g),len(g[0])
    twos=[(r,c) for r in range(h) for c in range(w) if g[r][c]==2]
    rows={r for r,c in twos}; cols={c for r,c in twos}
    if len(rows)==1:  # horizontal line: vertical gravity
        axis,brow=1,rows.pop()
        step=-1 if any(g[r][c]!=0 and g[r][c]!=2 and r<brow for r in range(h) for c in range(w)) else 1
    else:             # vertical line: horizontal gravity
        axis,brow=0,cols.pop()
        step=-1 if any(g[r][c]!=0 and g[r][c]!=2 and c<brow for r in range(h) for c in range(w)) else 1
    def get(r,c):
        return g[r][c] if axis==1 else g[c][r]
    H,W=(h,w) if axis==1 else (w,h)
    seen=[[False]*W for _ in range(H)]; objs=[]
    for r in range(H):
        for c in range(W):
            if get(r,c)!=0 and r!=brow and not seen[r][c]:
                v=get(r,c); stack=[(r,c)]; cells=[]; seen[r][c]=True
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and get(ny,nx)==v and ny!=brow:
                            seen[ny][nx]=True; stack.append((ny,nx))
                objs.append([v,cells])
    out=[[0]*w for _ in range(h)]
    for r,c in twos: out[r][c]=2
    def put(r,c,v):
        if axis==1: out[r][c]=v
        else: out[c][r]=v
    moved=True
    while moved:
        moved=False
        occ=set()
        for v,cells in objs: occ.update(cells)
        for o in objs:
            v,cells=o
            ocs=set(cells); ok=True
            for y,x in cells:
                ny=y+step
                if ny==brow or not (0<=ny<H) or ((ny,x) in occ and (ny,x) not in ocs):
                    ok=False; break
            if ok:
                for y,x in cells: put(y,x,0); occ.discard((y,x))
                o[1]=[(y+step,x) for y,x in cells]
                occ.update(o[1])
                for y,x in o[1]: put(y,x,v)
                moved=True
    return out
